from collections import defaultdict
from datetime import date, timedelta


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays is not None else set()
        # Maps (employee, year) to number of leave days used
        self._used_days: dict[tuple[str, int], int] = defaultdict(int)

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        """Request leave from start to end (inclusive); returns the number of leave days used."""
        if start > end:
            raise ValueError("Start date must not be after end date.")

        if (start - today).days < 3:
            raise ValueError("Leave requests must be made at least 3 days in advance.")

        # Count requested leave days partitioned by calendar year
        needed_by_year: dict[int, int] = defaultdict(int)
        current = start
        one_day = timedelta(days=1)

        while current <= end:
            if current.weekday() < 5 and current not in self.holidays:
                needed_by_year[current.year] += 1
            current += one_day

        # Validate that the employee has enough remaining days in each involved year
        for year, needed in needed_by_year.items():
            if needed > self.remaining(employee, year):
                raise ValueError(
                    f"Insufficient leave days remaining for year {year}: "
                    f"requested {needed}, available {self.remaining(employee, year)}."
                )

        # Deduct / record leave days
        for year, needed in needed_by_year.items():
            self._used_days[(employee, year)] += needed

        return sum(needed_by_year.values())

    def remaining(self, employee: str, year: int) -> int:
        """Returns the number of remaining leave days for an employee in a given year."""
        used = self._used_days.get((employee, year), 0)
        return self.days_per_year - used
```

